  // level berikutnya apa" dalam sekali lihat; apa pun yang tidak menjawab itu bukan di atas.
  const rows = (kotak.rows || []).map(([k, v]) =>
    `<div class="an-row"><span class="an-k">${esc(k)}</span><span class="an-v">${esc(v == null || v === '' ? '–' : v)}</span></div>`).join('');
  const tangga = (kotak.tangga || []).map(t =>
    `<div class="an-tg an-tg-${esc(t.jenis)}"><span class="an-tg-h">${esc(t.harga)}</span><span class="an-tg-l">${esc(t.label)}</span></div>`).join('');
  const bacaan = (kotak.bacaan || []).map(t => `<li>${esc(t)}</li>`).join('');
  const sk = (kotak.skenario || []).map(s =>
    `<div class="an-dz-r an-dz-${esc(s.kelas)}"><b>${esc(s.jika)}</b><span>${esc(s.maka)}</span>`
    + `<i class="an-tahap an-tahap-${esc(String(s.tahap).toLowerCase())}">${esc(s.tahap)}</i></div>`).join('');
